-- Reminders materialize normal assignments only under the global worker lock.
-- Calendar days with is_holiday=false retain the canonical DayContext behavior.
SET LOCAL ROLE sim_guru_owner;
CREATE OR REPLACE FUNCTION ops.reminders() RETURNS int LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE n int;BEGIN
 PERFORM app.ensure_occurrences(app.activity_today());
 INSERT INTO ops.domain_outbox(dedupe_key,recipient_id,subject,body)
 SELECT 'journal:'||a.id||':'||app.activity_today(),a.effective_user_id,'Jurnal belum lengkap','Periksa jurnal pembelajaran atau BAP kegiatan Anda pada SIM GURU.' FROM app.activity_assignments a JOIN app.activity_occurrences o ON o.id=a.occurrence_id WHERE o.date=app.activity_today() AND ((o.kind='KBM' AND coalesce((app.day_context_internal(o.date)->>'kbmEnabled')::boolean,false)) OR (o.kind='EXAM_SUPERVISOR' AND coalesce((app.day_context_internal(o.date)->>'examEnabled')::boolean,false))) AND (clock_timestamp() AT TIME ZONE 'Asia/Jakarta')>=o.date+o.time_end+interval '5 minutes' AND EXISTS(SELECT 1 FROM app.activity_confirmations c WHERE c.assignment_id=a.id AND c.revoked_at IS NULL) AND ((o.kind='KBM' AND NOT EXISTS(SELECT 1 FROM app.teaching_journals j WHERE j.occurrence_id=o.id AND j.deleted_at IS NULL)) OR (o.kind='EXAM_SUPERVISOR' AND NOT EXISTS(SELECT 1 FROM app.exam_baps b WHERE b.occurrence_id=o.id AND b.state='active'))) ON CONFLICT(dedupe_key) DO NOTHING;
 GET DIAGNOSTICS n=ROW_COUNT;
 INSERT INTO ops.domain_outbox(dedupe_key,recipient_id,subject,body)
 SELECT 'confirmation-reminder:'||o.id||':'||receiver.effective_user_id||':'||app.activity_today(),receiver.effective_user_id,'Konfirmasi kegiatan belum lengkap','Periksa kegiatan mengajar atau pengawas yang belum terkonfirmasi pada SIM GURU.' FROM app.activity_occurrences o JOIN app.activity_assignments target ON target.occurrence_id=o.id JOIN app.activity_occurrences duty ON duty.date=o.date AND ((o.kind='KBM' AND duty.kind='PIKET') OR (o.kind='EXAM_SUPERVISOR' AND duty.kind='EXAM_COMMITTEE')) JOIN app.activity_assignments receiver ON receiver.occurrence_id=duty.id WHERE o.date=app.activity_today() AND ((o.kind='KBM' AND coalesce((app.day_context_internal(o.date)->>'kbmEnabled')::boolean,false)) OR (o.kind='EXAM_SUPERVISOR' AND coalesce((app.day_context_internal(o.date)->>'examEnabled')::boolean,false))) AND target.effective_user_id<>receiver.effective_user_id AND (clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::time>=o.time_end AND NOT EXISTS(SELECT 1 FROM app.activity_confirmations c WHERE c.assignment_id=target.id AND c.revoked_at IS NULL) ON CONFLICT(dedupe_key) DO NOTHING;
 INSERT INTO ops.domain_outbox(dedupe_key,recipient_id,subject,body) SELECT 'event-journal:'||a.id||':'||app.activity_today(),a.user_id,'Jurnal acara belum lengkap','Kehadiran acara Anda tercatat. Lengkapi jurnal acara pada SIM GURU.' FROM app.event_attendance a JOIN app.event_definitions e ON e.id=a.event_id WHERE a.date=app.activity_today() AND e.active AND a.cancelled_at IS NULL AND (clock_timestamp() AT TIME ZONE 'Asia/Jakarta')::time>=e.time_end AND NOT EXISTS(SELECT 1 FROM app.event_journals j WHERE j.attendance_id=a.id AND j.cancelled_at IS NULL) ON CONFLICT(dedupe_key) DO NOTHING;
 RETURN n;END $$;
RESET ROLE;
